import { ProgressBar } from '@absoluteui/components/progress-bar';

const host = document.querySelector<HTMLElement>('#upload');
if (host) {
  const bar = ProgressBar.create(host, { label: 'Uploading report.pdf', value: 0 });
  const onProgress = (loaded: number, total: number): void => {
    bar.setValue((loaded / total) * 100);
    if (loaded >= total) bar.update({ tone: 'success' });
  };
  onProgress(5, 10);
}

import { ProgressBar } from '@absoluteui/components/progress-bar';

const host = document.querySelector<HTMLElement>('#import');
if (host) {
  const bar = ProgressBar.create(host, { label: 'Importing contacts', value: null, description: 'Preparing file' });
  bar.update({ max: 250, value: 40, description: 'Processing rows', valueText: (value, max) => `${String(value)} of ${String(max)} rows` });
}
